fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    // Assumes tol > 0
    // Check if the difference (a - b) lies strictly between -tol and +tol
    // Equivalently, |a - b| < tol
    let diff = a.wrapping_sub(b);
    diff > -tol && diff < tol
}

fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    // Assumes a.len() == b.len() > 0 and tol > 0
    //
    // For each index i, check if the difference between a[i] and b[i]
    // is strictly within (-tol, tol).
    // Use the scalar is_close_i8 function.
    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| is_close_i8(x, y, tol))
        .collect()
}